@startuml

class User {
  + userId : string
  + name : string
  + address : string
  + birthday : date
}

abstract class BusinessOwner {
  + linkedinAccount : string
}

abstract class HungryCustomer {
  + deliveryAddress : string
}

abstract class Entertainer {
  + stageName : string
  + bio : string
  + pricePer30Min : double
}

class PizzaRestaurant {
  + zipCode : string
  + address : string
  + phoneNumber : string
  + website : string
  + openingHours : string
}

class Pizza {
  + name : string
  + crustStructure : string
  + price : double
}

class Order {
  + orderId : string
  + dateTimePlaced : datetime
  + latestDeliveryTime : time
  + numberOfPeople : int
}

class EntertainmentOrder {
  + entertainmentType : string
  + duration : int
}

class Availability {
  + day : string
}

BusinessOwner --|> User
HungryCustomer --|> User
Entertainer --|> User

BusinessOwner "1" -- "1..*" PizzaRestaurant : owns
PizzaRestaurant "1" -- "1..*" Pizza : offers
HungryCustomer "1" -- "0..*" Order : places
Order "1" -- "1..*" Pizza : contains
Order "1" -- "0..1" EntertainmentOrder : is_type

Entertainer "1" -- "0..*" Availability : has
PizzaRestaurant "1" -- "0..*" Availability : works_at
Availability "0..*" -- "1" Entertainer : assigned_to
Availability "0..*" -- "1" PizzaRestaurant : assigned_to

EntertainmentOrder "0..*" -- "1" Entertainer : fulfilled_by

@enduml

